"""Lectura ACOTADA de suspensiones/reanudaciones: no certifica todo el padre."""
import copy
import hashlib
import re
import sys
import unittest
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'scripts'))
import build_base_referencia as b
from curation import load_speaker_reviews,validate_speaker_reviews
PRES='Rodrigo Vergara Montes'
MARSHALL='Enrique Marshall Rivera'

class LoopSixTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.raw={r[0]:dict(Fecha=b.to_date_str(r[1]),Texto=r[5],Actor=r[2]) for r in b.data}
        cls.reviews=load_speaker_reviews(cls.raw)
    def parts(self,p):
        r=self.raw[p]
        return b.segment_turns(r['Texto'],r['Fecha'],r['Actor'],review=self.reviews.get(p))
    def test_source_hashes_and_conservation(self):
        compact=lambda s:re.sub(r'\s+','',s)
        for p,e in FIXTURES.items():
            self.assertEqual(hashlib.sha256(self.raw[p]['Texto'].encode()).hexdigest(),e['hash'])
            self.assertEqual(compact(''.join(t for t,a,m in self.parts(p))),compact(self.raw[p]['Texto']))
    def test_clock_with_decimal_point_is_not_sentence_boundary(self):
        parts=self.parts(5313)
        self.assertIn('siendo la 13.05 horas',parts[-2][0])
        self.assertTrue(parts[-2][0].startswith('Al no formularse otros comentarios'))
        self.assertEqual(parts[-2][1],PRES)
        text='Siendo la 13.05 horas, el Presidente señor Rodrigo Vergara suspende la sesión.'
        self.assertEqual(len(b.split_sentences(text)),1)
    def test_closure_leads_reject_references_quotes_and_non_speech(self):
        for lead in ['Al no haber consultas o comentarios adicionales',
                     'Al no haber más comentarios','Al no formularse otros comentarios',
                     'Al no formularse otros comentarios, siendo la 13.05 horas',
                     'Al no formularse comentarios adicionales y siendo las 13:50 horas']:
            for tail in [', según el señor Presidente, la cifra cambia.',
                         ', el señor Presidente está presente.',
                         ', la opinión del señor Presidente indica una diferencia.']:
                self.assertIsNone(b.TURN_DETECTOR.speaker(lead+tail,'2015-11-12'))
            self.assertIsNone(b.TURN_DETECTOR.speaker('“'+lead+', el señor Presidente suspende la sesión.”','2015-11-12'))
    def test_closure_clock_and_prefix_are_bounded(self):
        for lead in ['Al no formularse otros comentarios, siendo las 25:10 horas',
                     'Al no formularse otros comentarios, siendo las 13:99 horas',
                     'Al no formularse otros comentarios del señor Marshall',
                     'Al no formularse otras preguntas']:
            self.assertIsNone(b.TURN_DETECTOR.speaker(lead+', el señor Presidente suspende la sesión.','2015-11-12'))
    def test_reopening_requires_explicit_act_and_valid_clock(self):
        for t in ['A las 16:00 horas, se reanuda la Reunión de Política Monetaria N° 208.',
                  'A las 15:30 horas, se reanuda la Reunión de Política Monetaria Nº203.']:
            self.assertTrue(b._inst_transition(t))
        for t in ['A las 16:00 horas, el Presidente comenta la reunión.',
                  'A las 25:00 horas, se reanuda la Reunión de Política Monetaria N° 208.',
                  'A las 16:99 horas, se reanuda la Reunión de Política Monetaria N° 208.',
                  'Señala que a las 16:00 horas, se reanuda la Reunión de Política Monetaria N° 208.',
                  '“A las 16:00 horas, se reanuda la Reunión de Política Monetaria N° 208.”']:
            self.assertFalse(b._inst_transition(t))
    def test_5548_personal_handoff_not_institutional_or_recipient(self):
        parts=self.parts(5548)
        self.assertEqual([a for t,a,m in parts],['Luis Óscar Herrera Barriga',PRES,b.CONSEJO,PRES])
        self.assertTrue(parts[-1][0].startswith('Antes de procederse a la presentación'))
        self.assertIn('Sergio Lehmann',parts[-1][0])
        self.assertTrue(self.raw[5549]['Texto'].startswith('El señor Sergio Lehmann señala'))
    def test_6583_marshall_opinion_between_garcia_and_president(self):
        parts=self.parts(6583)
        self.assertEqual([a for t,a,m in parts],['Pablo García Silva',MARSHALL,PRES,b.CONSEJO])
        self.assertEqual(len(parts[1][0]),126)
        self.assertTrue(parts[1][0].endswith('siguiendo la inflación subyacente.'))
    def test_review_intervals_are_complete(self):
        for p in [5548,6583]:
            rows=[dict(ID=i,ID_Padre=p,Texto=t,Actor_Final=a,Fuente_Actor=m) for i,(t,a,m) in enumerate(self.parts(p),1)]
            self.assertEqual(validate_speaker_reviews(rows,{p:self.reviews[p]}),[])
            next(r for r in rows if r['Fuente_Actor']=='CONTEXTO_REVISADO')['Texto']+=' añadido'
            self.assertTrue(validate_speaker_reviews(rows,{p:self.reviews[p]}))
    def test_source_damage_and_session_number_not_repaired(self):
        self.assertIn('H ^ .',self.parts(5798)[-2][0])
        self.assertIn('N° 227',self.parts(7145)[-1][0])
        self.assertIn('i,- Siendo',self.parts(4502)[-1][0])

    def test_second_cycle_source_hashes_and_conservation(self):
        for p,e in SECOND.items():
            self.assertEqual(hashlib.sha256(self.raw[p]['Texto'].encode()).hexdigest(),e['hash'])
            compact=lambda s:re.sub(r'\s+','',s)
            self.assertEqual(compact(''.join(t for t,a,m in self.parts(p))),compact(self.raw[p]['Texto']))
    def test_coordinated_adverbs_are_not_blind_global_splits(self):
        for p,count in [(4857,2),(6293,1),(7044,1)]:
            r=self.raw[p]
            self.assertEqual(len(b.segment_turns(r['Texto'],r['Fecha'],r['Actor'])),count)
    def test_coordinated_adverbs_reject_wrong_actor_and_quotes(self):
        for p in [4857,6293,7044]:
            r=self.raw[p];review=copy.deepcopy(self.reviews[p]);review['Actor']='Claudio Soto Gamboa'
            with self.assertRaisesRegex(ValueError,'límite válido'):
                b.segment_turns(r['Texto'],r['Fecha'],r['Actor'],review=review)
            for left,right in [('“','”'),('«','»'),('"','"')]:
                review=copy.deepcopy(self.reviews[p]);review['Inicio']+=1;review['Fin']+=1
                with self.assertRaisesRegex(ValueError,'límite válido'):
                    b.segment_turns(left+r['Texto']+right,r['Fecha'],r['Actor'],review=review)
    def test_vial_whole_vote_not_only_final_reflection(self):
        parts=self.parts(6050)
        self.assertTrue(parts[1][0].startswith('En el plano internacional, indica'))
        self.assertIn('su voto en esta ocasión es por bajarla a 4,25%',parts[1][0])
        self.assertIn('A título de reflexión final',parts[1][0])
        self.assertTrue(parts[1][0].endswith('economías'))
    def test_dissent_not_confused_with_president_majority(self):
        for p,rate,majority in [(6293,'3,75%','4,0%'),(7044,'3,25%','3%')]:
            parts=self.parts(p)
            self.assertIn(rate,parts[1][0]);self.assertIn(majority,parts[2][0])
            self.assertTrue(parts[1][0].startswith('y'))
    def test_soto_adviser_and_preserved_footer(self):
        parts=self.parts(6730)
        self.assertIn('B A N C O C E N T R A L D E C H I L E',parts[1][0])
        self.assertEqual(b.roster_role_for('2015-04-16','Claudio Soto Gamboa'),'Asesor del Ministerio de Hacienda')
    def test_second_cycle_review_intervals_reject_truncation(self):
        for p in SECOND:
            rows=[dict(ID=i,ID_Padre=p,Texto=t,Actor_Final=a,Fuente_Actor=m) for i,(t,a,m) in enumerate(self.parts(p),1)]
            self.assertEqual(validate_speaker_reviews(rows,{p:self.reviews[p]}),[])
            next(r for r in rows if r['Fuente_Actor']=='CONTEXTO_REVISADO')['Texto']+=' añadido'
            self.assertTrue(validate_speaker_reviews(rows,{p:self.reviews[p]}))

    def test_third_cycle_sources_and_whole_intervals(self):
        for p,e in THIRD.items():
            self.assertEqual(hashlib.sha256(self.raw[p]['Texto'].encode()).hexdigest(),e['hash'])
            parts=self.parts(p)
            self.assertEqual([a for t,a,m in parts],e['actors'])
            self.assertEqual([len(t) for t,a,m in parts],e['lengths'])
            self.assertEqual(''.join(''.join(t.split()) for t,a,m in parts),''.join(self.raw[p]['Texto'].split()))
            if p in self.reviews:
                rows=[dict(ID=i,ID_Padre=p,Texto=t,Actor_Final=a,Fuente_Actor=m) for i,(t,a,m) in enumerate(parts,1)]
                self.assertEqual(validate_speaker_reviews(rows,{p:self.reviews[p]}),[])
    def test_vicuna_precision_does_not_absorb_soto_presentation(self):
        parts=self.parts(5418)
        self.assertIn('desde 6,7% a 6,5%',parts[1][0])
        self.assertIn('Al proseguir con su presentación',parts[2][0])
        self.assertTrue(parts[2][0].endswith('6,1% a 7,3%.'))
    def test_imports_precision_is_soto_before_president(self):
        parts=self.parts(5615)
        self.assertIn('12% en términos nominales y a 16%',parts[1][0])
        self.assertEqual(parts[1][1],'Claudio Soto Gamboa')
        self.assertTrue(parts[2][0].startswith('Al no formularse otros comentarios'))
    def test_new_mentions_do_not_modify_rows_or_suppress_warnings(self):
        from mention_reviews import load_mention_reviews,validate_mention_reviews
        reviews={k:r for k,r in load_mention_reviews(self.raw).items() if r['ID_Padre'] in [5658,6587]}
        rows=[]
        for p in [5658,6587]:
            for t,a,m in self.parts(p):rows.append(dict(ID=len(rows)+1,ID_Padre=p,Fecha=self.raw[p]['Fecha'],Texto=t,Actor_Final=a,Motivos_Revision='POSIBLE_OTRO_HABLANTE_O_MENCION'))
        before=copy.deepcopy(rows);errors,ann=validate_mention_reviews(rows,reviews)
        self.assertEqual(errors,[]);self.assertEqual(len(ann),2);self.assertEqual(rows,before)
        for p in [5658,6587]:
            changed=copy.deepcopy(rows)
            next(r for r in changed if r['ID_Padre']==p)['Texto']+=' añadido'
            self.assertTrue(validate_mention_reviews(changed,reviews)[0])
    def test_foreign_president_and_minister_remain_references(self):
        self.assertIn('su reciente visita al Banco Central de Reserva de Perú',self.parts(5658)[0][0])
        self.assertEqual(len(self.parts(5658)),1)
        self.assertIn('Como mencionó el Ministro de Hacienda',self.parts(6587)[0][0])
        self.assertEqual(len(self.parts(6587)),1)
    def test_intercalated_vicuna_rejects_quote_and_wrong_actor(self):
        p=5418;r=self.raw[p];review=copy.deepcopy(self.reviews[p]);review['Actor']=PRES
        with self.assertRaisesRegex(ValueError,'límite válido'):
            b.segment_turns(r['Texto'],r['Fecha'],r['Actor'],review=review)
        review=copy.deepcopy(self.reviews[p]);review['Inicio']+=1;review['Fin']+=1
        with self.assertRaisesRegex(ValueError,'límite válido'):
            b.segment_turns('“'+r['Texto']+'”',r['Fecha'],r['Actor'],review=review)

